insert into marketing.settings (key, value) values ('meta', '{"urls":{"fanlife":"https://fanlife.dubelteam.com","theworker":"https://theworker.dubelteam.com","dubid":"https://dubid.dubelteam.com","offsides":"https://offsides.dubelteam.com","fuckyou":"https://fuckyou.dubelteam.com"},"names":{"fanlife":"FAN LIFE","theworker":"THE WORKER","dubid":"DUBID","offsides":"OFFSIDES","fuckyou":"FUCK YOU","all":"DUBEL TEAM"},"tags":{"fanlife":"#FANLIFE #FootballForever #Football #Supporters #DubelTeam","theworker":"#TheWorker #HapoelTelAviv #Hapoel #FootballHistory #DubelTeam","dubid":"#DUBID #Fantasy #IsraeliFootball #LigatHaAl #DubelTeam","offsides":"#OFFSIDES #Predictions #Football #MatchDay #DubelTeam","fuckyou":"#FUCKYOU #Derby #Terrace #DubelTeam","all":"#DubelTeam #Football #Supporters #FootballForever"},"platform":{"post":"Instagram · Facebook · TikTok (photo)","carousel":"Instagram carousel · Facebook album · TikTok photo mode","reel":"TikTok · Instagram Reels · Facebook Reels","story":"Instagram Story · Facebook Story","background":"Instagram Story · TikTok photo · Facebook Story","text":"Facebook · Instagram (text on background) · TikTok text post"},"format_he":{"post":"Post","carousel":"Carousel","reel":"Reel / TikTok","story":"Story","background":"Wallpaper / background","text":"Text post"},"clubs":{"Hapoel Tel Aviv":"hapoel-tel-aviv","Hapoel Petah Tikva":"hapoel-petah-tikva","Olympiacos":"olympiacos","Panathinaikos":"panathinaikos","AEK Athens":"aek-athens","Celtic":"celtic","St. Pauli":"st-pauli","Zrinjski Mostar":"zrinjski-mostar"},"derby_pairs":[["Hapoel Tel Aviv","Maccabi Tel Aviv"],["Maccabi Haifa","Hapoel Haifa"],["Beitar Jerusalem","Hapoel Jerusalem"]],"big_names":["Barcelona","Real Madrid","Atlético Madrid","Liverpool","Arsenal","Manchester City","Manchester United","Chelsea","Tottenham Hotspur","PAOK","Maccabi Tel Aviv","Maccabi Haifa","Beitar Jerusalem","Hapoel Beer Sheva"]}'::jsonb)
