insert into marketing.settings (key, value) values ('content', '{"MORNING":[{"app":"all","hook":"You don’t choose a club. It chooses you.","body":"It started with your father’s hand, the steps, the smell of sunflower seeds.\nYears went by, the shirts changed — the love didn’t.\nWe built one place for everything a supporter feels. Good morning, family.","visual":"T1 Quote card. Grainy archive photo: a father’s hand and a child’s hand on a stand railing."},{"app":"fanlife","hook":"Same club. Different journeys. One universe.","body":"FAN LIFE is the supporter’s home: 13 gates of games, a living archive, and the story of your life with your club.\nOlympiacos, Panathinaikos, AEK, Hapoel, Celtic and more — each with a world of its own.","visual":"T3 Club collage: 8 crests in circles, big FAN LIFE masthead."},{"app":"theworker","hook":"Some people remember dates. We remember goals.","body":"THE WORKER is the Hapoel Tel Aviv history game — 13 gates, like Bloomfield.\nWho started the final? Which sponsor was on the shirt? Prove it to yourself.","visual":"T1 Quote card. Gate 5 of Bloomfield, red-and-navy screenprint on cream."},{"app":"all","hook":"What’s the first thing you check in the morning?","body":"Not emails. Not the news.\nThe table. The squad. What they said in the studio last night.\nIf that’s you — you’re in the right place.","visual":"T1 Quote card. Phone next to a coffee cup, a blurred league table on screen."},{"app":"dubid","hook":"One player from every club. That’s the only rule.","body":"DUBID is fantasy for the Israeli Premier League — with a neighbourhood twist: you pick just one player from each club.\nEasy to learn, hard to win.","visual":"T2 App feature card. A grid of 14 hand-drawn crests, a player silhouette in each."},{"app":"all","hook":"Your team lost. You’re still here.","body":"That’s the difference between a viewer and a supporter.\nA viewer changes the channel. A supporter only changes socks — for luck.\nGood morning to everyone who stayed.","visual":"T1 Quote card. Black-and-white empty stand after a match, one scarf left on a seat."},{"app":"offsides","hook":"Every match is 90 minutes of “told you so”.","body":"OFFSIDES: prediction arenas with your friends, live flash questions, and a table that shows who really knows.\nA free simulation game — no real money, only bragging rights.","visual":"T2 App feature card. A flash question “Who scores first?” in stadium-lights style."},{"app":"theworker","hook":"Hapoel isn’t a team. It’s a class.","body":"A hundred years of red. Of workers, of Ussishkin, of Bloomfield.\nTHE WORKER keeps all of it — and lets you play with it.","visual":"T1 Quote card. The historic Hapoel mark as an aged screenprint."},{"app":"fanlife","hook":"Your story with your club deserves telling.","body":"FAN LIFE has LIFE — a supporter’s life simulation: childhood, matchdays, promises, friends.\nEvery choice changes the story.","visual":"T2 App feature card. Pixel-art kid in a red shirt facing a stadium gate."},{"app":"all","hook":"The smell of grass on a Saturday afternoon.","body":"You can’t explain it to someone who wasn’t there.\nSo we built it for you.\nTag the person who took you to your first match.","visual":"T1 Quote card. Close-up of grass, a chalk line and an old studded boot."},{"app":"dubid","hook":"Which player would you take from your ex’s club?","body":"In DUBID you have to pick one even from the club you hate.\nThat’s the moment a supporter becomes a strategist.","visual":"T6 Meme card. Two buttons: “Pick their star” / “Pick their bench”. Sweat."},{"app":"all","hook":"Do you have a shirt you never wash before a match?","body":"We all believe a little.\nTell us your ritual in the comments — the craziest one gets a post.","visual":"T1 Quote card. A folded shirt on a chair, morning light, text “Your ritual?”."},{"app":"fanlife","hook":"How well do you really know your club?","body":"Trivia in four levels — Easy, Medium, Hard, Expert. Every question from your club’s real archive.\nNo guessing, only facts.","visual":"T2 App feature card. Magazine-style question card, four buttons in four colours."},{"app":"offsides","hook":"The smartest friend in the group chat? We’ll see.","body":"Open an arena on OFFSIDES, send the link, and everyone predicts before kick-off.\nThe table doesn’t lie.","visual":"T6 Meme card. A group-chat screenshot with an arena link and a 🧨 emoji."},{"app":"theworker","hook":"Every player wore a shirt. We know which one.","body":"In THE WORKER every player wears the original shirt of the season he played.\n168 documented shirts, from 1949 to today.","visual":"T4 Kit card. A wall of red shirts on hangers, ordered by decade."},{"app":"all","hook":"Would you skip a wedding for a derby?","body":"Don’t answer too fast. We already know.","visual":"T6 Meme card. Big text on red: “Wedding or derby?” with two options."},{"app":"fanlife","hook":"Some goals stay forever.","body":"In FAN LIFE’s gate 8 you rebuild a historic goal touch by touch: drag the players, pass, shoot.\nThen watch the original.","visual":"T2 App feature card. A drawn pitch diagram with the arrows of a goal move."},{"app":"dubid","hook":"Is your Saturday pick ready?","body":"The round is close. 14 clubs, 14 players, one captain.\nWhoever waits for the last minute misses out.","visual":"T5 Countdown card. An hourglass with club crests falling through it."},{"app":"all","hook":"Football isn’t life. It’s better.","body":"Because in life there are no 90 minutes when a whole city breathes together.\nGood morning, supporters. ❤️","visual":"T1 Quote card. Panorama of a full stand with coloured smoke, heavy film grain."},{"app":"theworker","hook":"Your grandfather was at Bloomfield. Were you?","body":"Questions about matches played before you were born — answer right and you’ll feel you were there.","visual":"T1 Quote card. An old torn Bloomfield ticket."},{"app":"offsides","hook":"You predict scores in your head every weekend. Now it counts.","body":"Points for the exact score, for half-time, for who scores first.\nAnd a daily streak for those who come back every day.","visual":"T2 App feature card. An old scoreboard with 🔥 points beside each pick."},{"app":"fanlife","hook":"Build your all-time XI.","body":"Gate 1 in FAN LIFE: 11 players from your club’s whole history. No ratings, no referees. Just you.","visual":"T2 App feature card. Top-down pitch with 11 vintage shirts in a 4-3-3."},{"app":"all","hook":"Remember where you watched the biggest goal of your life?","body":"We do. It’s in our archive.\nTell us in the comments — which match made you cry?","visual":"T1 Quote card. A 90s living room, an old TV, friends jumping."},{"app":"dubid","hook":"A little neighbourhood, a lot of football.","body":"DUBID was born on a bench: “one from every club, and let’s see who knows”.\nNow it’s an app.","visual":"T1 Quote card. A street bench, three friends arguing over a sports paper."},{"app":"theworker","hook":"The hardest gate in THE WORKER? Gate 11.","body":"It’s the away end. No red there at all.\nWhoever walks in is looking at somebody else’s poster.","visual":"T1 Quote card. A navy gate numbered 11, not a touch of red."},{"app":"fanlife","hook":"Every club deserves a home of its own.","body":"In FAN LIFE every club has a world: colours, terrace, favourite gate, games and a story.\nPick yours.","visual":"T3 Club collage. Eight doors in eight club colours, comic-book style."},{"app":"all","hook":"Real supporter vs. supporter? There’s no difference.","body":"If you love it, you’re a supporter. No matter how many matches, no matter how much money.\nEveryone’s welcome.","visual":"T1 Quote card. People of all ages in scarves, arms around each other, backs to camera."},{"app":"offsides","hook":"Flash question: next corner — goal or not?","body":"On OFFSIDES the questions pop up during the match. 30 seconds to answer.\nIt’s like watching the game twice.","visual":"T2 App feature card. Huge yes/no buttons over a night pitch with a countdown."},{"app":"fanlife","hook":"Blind Cow: who’s the player?","body":"Clue after clue — season, number, match — guess the player as fast as you can.\nPlay a live duel with a friend too.","visual":"T2 App feature card. A player silhouette with a question mark, clues as sticky notes."},{"app":"all","hook":"Thank you for being here.","body":"A whole month of football, memories and games on this page.\nTurn on notifications so you don’t miss a thing.","visual":"T1 Quote card. Magazine poster: “Thank you” handwritten, DUBEL TEAM stamp."}],"CAROUSEL":[{"app":"fanlife","hook":"13 gates. 13 games. One club.","body":"Slide 1: 13 gates — which one is yours?\nSlide 2: All-time XI\nSlide 3: Trivia in 4 levels\nSlide 4: Rebuild a historic goal\nSlide 5: The kit game — build the shirt of the right season","visual":"T7 Carousel. 5 slides in 1972 magazine style, a numbered gate on each."},{"app":"dubid","hook":"How to play DUBID in 30 seconds","body":"Slide 1: Pick one player from every club\nSlide 2: Pick a captain (double points)\nSlide 3: Players score for goals, assists and clean sheets\nSlide 4: A table against the whole country\nSlide 5: Send your lineup to your friends","visual":"T7 Carousel. 5 comic frames, a hand picking cards."},{"app":"offsides","hook":"OFFSIDES: a beginner’s guide","body":"Slide 1: Open an arena for a match\nSlide 2: Invite friends with a link\nSlide 3: Predict half-time, full-time and who scores first\nSlide 4: Flash questions during the match\nSlide 5: Table, podium and a winner’s story. No real money.","visual":"T7 Carousel. Dark slides with orange stadium lights."},{"app":"theworker","hook":"5 things you didn’t know about Hapoel’s shirts","body":"Slide 1: Every decade had its own crest\nSlide 2: The crest changes with the cloth colour\nSlide 3: Some sponsors were local businesses\nSlide 4: 168 documented shirts\nSlide 5: Build one yourself — gate 4","visual":"T7 Carousel. A different archive shirt on each slide, an arrow on one detail."},{"app":"fanlife","hook":"LIFE: a supporter’s life, simulated","body":"Slide 1: You start as a kid\nSlide 2: Your first walk to the ground\nSlide 3: Friends, family, promises\nSlide 4: Every choice changes the story\nSlide 5: What kind of supporter will you be?","visual":"T7 Carousel. Pixel art: the same character at 5 ages."},{"app":"all","hook":"Five apps. One supporter.","body":"Slide 1: FAN LIFE — the home\nSlide 2: THE WORKER — Hapoel, in depth\nSlide 3: DUBID — Israeli Premier League fantasy\nSlide 4: OFFSIDES — live predictions with friends\nSlide 5: FUCK YOU — derby days only 😉","visual":"T7 Carousel. Five cards in five colours tied by a red thread."},{"app":"dubid","hook":"Mistakes that cost you a DUBID round","body":"Slide 1: Picking only stars\nSlide 2: Forgetting to check injuries\nSlide 3: A captain playing away\nSlide 4: Leaving last week’s lineup\nSlide 5: Not sending it to your friends (and not teasing them)","visual":"T7 Carousel. “Don’t do this” style with red crosses."},{"app":"fanlife","hook":"Royal Rumble: your XI on a budget","body":"Slide 1: €33–35M to build 11\nSlide 2: Every player has a price\nSlide 3: Spin, pick a line, sign\nSlide 4: Play a friend through a link\nSlide 5: Who built better?","visual":"T7 Carousel. A slot machine with vintage player cards."},{"app":"offsides","hook":"3 tips to win an arena","body":"Slide 1: Exact score = 5 points\nSlide 2: The Boost doubles one question — but you don’t know which\nSlide 3: Flash questions are where you climb\nSlide 4: A daily streak builds an edge\nSlide 5: And most important — tease them in the chat","visual":"T7 Carousel. Orange-and-blue infographic with icons."},{"app":"theworker","hook":"Hapoel’s timeline — put it in order","body":"Slide 1: An event\nSlide 2: An event\nSlide 3: An event\nSlide 4: Which came first?\nSlide 5: Gate 13 in THE WORKER — the timeline","visual":"T7 Carousel. A red timeline with face-down cards."},{"app":"fanlife","hook":"Legends Manager: manage the legends","body":"Slide 1: Draft your club’s legends\nSlide 2: A full season against real clubs\nSlide 3: Captain, substitutions, tactics\nSlide 4: Pixel match highlights\nSlide 5: Will you win the title?","visual":"T7 Carousel. The shiny Legends Manager badge on a night background."},{"app":"all","hook":"How to survive a week without football (you can’t)","body":"Slide 1: Sunday — trivia\nSlide 2: Monday — rebuild a goal\nSlide 3: Tuesday — draft legends\nSlide 4: Wednesday — the kit archive\nSlide 5: Thursday — your lineup for the weekend","visual":"T7 Carousel. A hand-drawn weekly planner, one activity a day."},{"app":"dubid","hook":"The captain: the decision that wins rounds","body":"Slide 1: The captain scores double\nSlide 2: Home match > away match\nSlide 3: Who’s in form — not who’s famous\nSlide 4: A weak opponent is a chance\nSlide 5: So — who’s your captain?","visual":"T7 Carousel. A captain’s armband, dramatic close-up."},{"app":"fanlife","hook":"Away Days: every ground your club played in Europe","body":"Slide 1: A map of every away match\nSlide 2: Every ground with a photo\nSlide 3: An “I was there” button\nSlide 4: “My journey” builds itself\nSlide 5: Where were you?","visual":"T7 Carousel. An ink map of Europe, red lines between cities."},{"app":"offsides","hook":"Momentum: predict the next few minutes","body":"Slide 1: The app asks: a goal in the next 10 minutes?\nSlide 2: The odds move with the match\nSlide 3: Answer yes or no\nSlide 4: Get it right, climb\nSlide 5: All virtual, all fun","visual":"T7 Carousel. A live momentum graph with a jumping arrow."},{"app":"theworker","hook":"Hapoel polls: no fake counts","body":"Slide 1: The best centre-back?\nSlide 2: The striker?\nSlide 3: The captain?\nSlide 4: A printed ballot slip\nSlide 5: Share your slip","visual":"T7 Carousel. A printed ballot with 8 rows and X marks."},{"app":"fanlife","hook":"The kit archive: from 1949 to today","body":"Slide 1: A shirt from the archive\nSlide 2: A shirt\nSlide 3: A shirt\nSlide 4: Which is the most beautiful?\nSlide 5: Design your own in the studio","visual":"T4 Kit card ×5. Clean product shots on fabric."},{"app":"all","hook":"What kind of supporter are you?","body":"Slide 1: The analyst — OFFSIDES\nSlide 2: The manager — DUBID / Legends Manager\nSlide 3: The historian — THE WORKER\nSlide 4: The nostalgic — FAN LIFE LIFE\nSlide 5: The angry one — FUCK YOU (derbies only)","visual":"T7 Carousel. Five comic characters, each with a prop."},{"app":"dubid","hook":"Stats that are worth points","body":"Slide 1: Who scores in every home match?\nSlide 2: Which keeper keeps clean sheets?\nSlide 3: Who assists the most?\nSlide 4: Who’s injured?\nSlide 5: It’s all on the player card in DUBID","visual":"T7 Carousel. Newspaper-style stat tables."},{"app":"fanlife","hook":"Your club’s memory game","body":"Slide 1: Face-down cards\nSlide 2: Every pair — a moment in history\nSlide 3: Find a pair, read the story\nSlide 4: Against the clock\nSlide 5: Gate 6 in FAN LIFE","visual":"T7 Carousel. A grid of face-down cards, two turned over."},{"app":"offsides","hook":"Duel: you against one friend","body":"Slide 1: Pick a match\nSlide 2: Challenge a friend\nSlide 3: You both predict\nSlide 4: The more accurate one wins\nSlide 5: Revenge next match","visual":"T7 Carousel. Two player cards face to face, lightning between them."},{"app":"theworker","hook":"The lineup quiz: who started the final?","body":"Slide 1: A historic match\nSlide 2: 11 empty slots\nSlide 3: Drag the players in\nSlide 4: Check\nSlide 5: How many did you get?","visual":"T7 Carousel. A pitch with 11 empty circles and a squad list."},{"app":"fanlife","hook":"The shirt market: buy, swap, complete","body":"Slide 1: Have / Want\nSlide 2: Your shirt closet\nSlide 3: Matches with collectors\nSlide 4: Chat without phone or email\nSlide 5: No commission","visual":"T7 Carousel. An open closet of shirts with handwritten price tags."},{"app":"all","hook":"30 days, 240 posts, one goal","body":"Slide 1: Connect supporters\nSlide 2: Keep memories\nSlide 3: Play together\nSlide 4: Laugh at the rival\nSlide 5: Follow — it’s only the start","visual":"T7 Carousel. Big magazine-style numbers."},{"app":"dubid","hook":"DUBID vs. regular fantasy","body":"Slide 1: Regular fantasy — 15 players, budget, transfers\nSlide 2: DUBID — 1 from every club\nSlide 3: No prices, only decisions\nSlide 4: Every club matters\nSlide 5: Try one round","visual":"T7 Carousel. Side-by-side comparison, ✔ and ✘."},{"app":"fanlife","hook":"Fan Passport: your file","body":"Slide 1: The games you played\nSlide 2: The shirts you built\nSlide 3: The grounds you visited\nSlide 4: Your lineups\nSlide 5: All in one place","visual":"T7 Carousel. A supporter’s passport with ground stamps."},{"app":"offsides","hook":"Why there’s no real money on OFFSIDES","body":"Slide 1: Because the fun is being right\nSlide 2: 🧨 is a virtual currency only\nSlide 3: It can’t be cashed out\nSlide 4: Nobody loses money\nSlide 5: Anyone can be the best","visual":"T7 Carousel. A drawn 🧨 coin with a “€0” band."},{"app":"theworker","hook":"Ussishkin: the memorial wing","body":"Slide 1: The hall\nSlide 2: The nights\nSlide 3: The crowd\nSlide 4: The end\nSlide 5: The memory stays — in THE WORKER","visual":"T7 Carousel. An old basketball hall in warm light."},{"app":"fanlife","hook":"The kit game: build the shirt","body":"Slide 1: A blank shirt\nSlide 2: Cut and colour\nSlide 3: Sleeves and sponsor\nSlide 4: Maker and crest\nSlide 5: Is it the right season?","visual":"T7 Carousel. A shirt built layer by layer."},{"app":"all","hook":"Save this post for the weekend","body":"Slide 1: 12:00 — your DUBID lineup\nSlide 2: Before kick-off — an OFFSIDES arena\nSlide 3: Half-time — trivia\nSlide 4: After — rebuild the goal\nSlide 5: At night — your story in LIFE","visual":"T7 Carousel. A drawn matchday planner with times and icons."}],"GAMEDAY":[{"app":"dubid","hook":"Checked your lineup today?","body":"Injuries, suspensions, predicted lineups — it all changes until the last minute.\nMake sure your players are playing.","visual":"T2 App feature card. A checklist with green ticks and one player in red."},{"app":"offsides","hook":"The first arena is on you.","body":"Easy: open an arena, send it to your friends — we’ll be waiting on the podium.","visual":"T2 App feature card. A 1-2-3 podium with drawn crowns."},{"app":"dubid","hook":"Who’s your captain this week?","body":"Tell us in the comments. If he scores — come back and brag. If not — we saw nothing.","visual":"T6 Meme card. A captain’s armband on red, question mark."},{"app":"offsides","hook":"Is your streak still alive?","body":"Day one, day two, day three… every day you come back, the streak grows 🔥","visual":"T2 App feature card. A neon flame with a day counter."},{"app":"dubid","hook":"The most underrated player in the league?","body":"There’s always one everybody forgets — and he brings points every week. Who’s yours?","visual":"T6 Meme card. A player silhouette labelled “underrated”."},{"app":"offsides","hook":"Your friends think they know football.","body":"Prove otherwise. One arena, 90 minutes, one truth.","visual":"T6 Meme card. “Told you so” printed on a shirt."},{"app":"dubid","hook":"The hardest pick: from the club you hate.","body":"In DUBID there’s no way out — one from every club. Who did you pick “in pain”?","visual":"T6 Meme card. A disgusted emoji holding a player card."},{"app":"offsides","hook":"Question of the week: who scores first this weekend?","body":"Predict it in the next arena — and keep the screenshot for revenge.","visual":"T2 App feature card. A question card with 3 options."},{"app":"dubid","hook":"The DUBID table is updating. Where are you?","body":"Every goal, every assist, every clean sheet moves you. Check your position.","visual":"T2 App feature card. A table with a green arrow by a made-up name."},{"app":"offsides","hook":"The Boost: the biggest (virtual) risk","body":"One random question doubled — and you don’t know which. Who dares?","visual":"T2 App feature card. A glowing BOOST ×2 button."},{"app":"dubid","hook":"New round = fresh start.","body":"Whatever happened last week, the new lineup starts from zero.","visual":"T5 Countdown card. A torn calendar page, “New round” underneath."},{"app":"offsides","hook":"Yesterday’s podium","body":"Who climbed? Who fell? Who didn’t even play? Yesterday’s arenas are closed — the table speaks.","visual":"T2 App feature card. A podium with three stars and a “?”."},{"app":"dubid","hook":"The home player or the away player?","body":"Same club, two good players. A tough away match. What do you do?","visual":"T6 Meme card. Two cards with ⚖️ between them."},{"app":"offsides","hook":"How many points is an exact score worth?","body":"Five. The maximum. That’s why everyone tries — and few get it.","visual":"T2 App feature card. A huge 5 in smoke."},{"app":"dubid","hook":"Lineup ready — share it?","body":"Every lineup has a share card. Post a story and tag us.","visual":"T2 App feature card. A lineup card in story format."},{"app":"offsides","hook":"Friends arena or public arena?","body":"Friends is for teasing. Public is for proving. Why choose? Do both.","visual":"T6 Meme card. Two doors: “The crew” / “The whole country”."},{"app":"dubid","hook":"Ever had your captain not play?","body":"We’ve all been there. This week, check the lineups before you lock.","visual":"T6 Meme card. A captain on the bench with a cup of tea."},{"app":"offsides","hook":"Flash questions are where you win.","body":"They come with no warning. Keep the app open during the match.","visual":"T2 App feature card. A phone notification “⚡ Flash question!”."},{"app":"dubid","hook":"Can you win without stars?","body":"In DUBID — yes. The secret: players who play 90 minutes every week.","visual":"T2 App feature card. An ordinary player with an orange halo."},{"app":"offsides","hook":"Your half-time prediction?","body":"Most people ignore half-time. That’s where the cheap points are.","visual":"T2 App feature card. A scoreboard with HT highlighted."},{"app":"dubid","hook":"Last week’s lineup still there?","body":"If you didn’t change it, it stays. Make sure that’s what you want.","visual":"T6 Meme card. A dusty lineup with cobwebs."},{"app":"offsides","hook":"How many arenas are open right now?","body":"There’s always a match coming. Open, invite, predict.","visual":"T2 App feature card. A match list with “Open arena” buttons."},{"app":"dubid","hook":"A private league with your work friends?","body":"Everyone talks football on Monday. Now there’s a table.","visual":"T2 App feature card. A table with made-up names like “Dave from accounts”."},{"app":"offsides","hook":"Momentum: a goal in the next 10 minutes?","body":"The most tense question of the match — and you answer it mid-game.","visual":"T2 App feature card. A 10-minute clock with a burning ball."},{"app":"dubid","hook":"Clean-sheet points — for defenders too?","body":"Yes. That’s why the big club’s centre-back is sometimes the smartest pick.","visual":"T2 App feature card. A defender mid-tackle, an orange shield."},{"app":"offsides","hook":"Predictor of the week","body":"Every week someone gets everything right. This week it could be you.","visual":"T2 App feature card. A small drawn trophy with a question mark."},{"app":"dubid","hook":"Busy fixture list?","body":"When the calendar is packed — rotation. Think who will rest.","visual":"T5 Countdown card. A calendar with red marks."},{"app":"offsides","hook":"The best story of the week","body":"Won an arena? Your winner’s story is ready to share. Tag us.","visual":"T2 App feature card. A winner’s story with fireworks."},{"app":"dubid","hook":"How many players from your club are in your lineup?","body":"In DUBID — just one. That’s what makes it fun.","visual":"T2 App feature card. One crest inside 14 circles."},{"app":"offsides","hook":"Month’s over — who rules the arenas?","body":"Monthly recap: the sharpest predictions, the longest streaks. Thanks for being with us.","visual":"T2 App feature card. A crown over a table, confetti."}],"REELS":[{"app":"fanlife","hook":"POV: explaining to your partner why you’re sad on a Sunday","body":"0–3s: gutted face on the sofa.\n3–8s: her: “It’s just a game.”\n8–15s: slow zoom, dramatic music.\n15–20s: cut to FAN LIFE — “There’s a place that gets you.”","visual":"T8 Reel cover. 20s, trending dramatic sound, on-screen text."},{"app":"dubid","hook":"Picking a DUBID lineup in real time","body":"0–3s: “I’ve got 30 seconds to pick 14 players.”\n3–20s: fast screen recording, voice reactions.\n20–25s: “Locked. Who wants to beat me?” + link in bio.","visual":"T8 Reel cover. Screen recording + face cam in the corner, 25s."},{"app":"offsides","hook":"When the friend who said “easy 3–0” sees it’s 0–1","body":"0–2s: screenshot of his prediction.\n2–6s: the score.\n6–12s: dramatic reaction.\n12–15s: “See you in the next arena.”","visual":"T8 Reel cover. Meme format, 15s, “oh no” sound."},{"app":"theworker","hook":"Only real Hapoel supporters get this one","body":"0–3s: a question from THE WORKER on screen.\n3–8s: countdown.\n8–10s: the answer.\n10–15s: “12 more gates like this.”","visual":"T8 Reel cover. Big type, ticking clock, 15s."},{"app":"all","hook":"A supporter before and after a 90th-minute goal","body":"0–5s: silence, tense face, nails.\n5–6s: cut.\n6–15s: jumping, screaming, hugging a stranger.\n15–18s: “That’s why we’re here.”","visual":"T8 Reel cover. Short comedy, 18s."},{"app":"fanlife","hook":"Rebuilding a historic goal in gate 8","body":"0–3s: “I tried to rebuild the most famous goal.”\n3–20s: screen recording — drags, passes, shot.\n20–28s: side by side with the original.\n28–30s: “How close was I?”","visual":"T8 Reel cover. 30s screen recording with voice-over."},{"app":"offsides","hook":"A flash question in the middle of family dinner","body":"0–4s: family dinner.\n4–6s: notification “⚡ Flash question”.\n6–12s: he answers under the table.\n12–15s: mum: “What are you doing?” — “Nothing.”","visual":"T8 Reel cover. Sketch, 15s."},{"app":"dubid","hook":"3 players nobody picks — who bring points","body":"0–3s: “Nobody picks them.”\n3–18s: three cards, one argument each (no invented stats — only “plays every minute”, “takes the penalties”).\n18–22s: “Who’s the fourth? Comments.”","visual":"T8 Reel cover. Flipping cards, 22s."},{"app":"fanlife","hook":"Building the right season’s shirt — no cheating","body":"0–3s: a blank shirt.\n3–20s: dragging parts, second thoughts.\n20–25s: “Check the shirt” — result.","visual":"T8 Reel cover. Screen recording with a click sound."},{"app":"all","hook":"Things only supporters understand","body":"Line 1: turning the anthem up in the car.\nLine 2: not washing the shirt.\nLine 3: waiting all week for the weekend.\nLine 4: crying over a goal from 20 years ago.\nEnd: “Tag someone who’s this.”","visual":"T8 Reel cover. Text changing over a stand, 20s."},{"app":"theworker","hook":"My grandad quizzes me on Hapoel","body":"0–3s: grandad in a cap.\n3–15s: questions from THE WORKER, grandson stumbles.\n15–20s: grandad: “You know nothing.” Link in bio.","visual":"T8 Reel cover. Warm two-generation sketch, 20s."},{"app":"offsides","hook":"Boost ×2: the moment it all flipped","body":"0–5s: “I put the Boost on.”\n5–12s: waiting to see which question.\n12–18s: reaction (good or bad).\n18–20s: “Would you have risked it?”","visual":"T8 Reel cover. Tension drums, 20s."},{"app":"fanlife","hook":"Blind Cow against a friend — live","body":"0–3s: “Duel: who names the player first.”\n3–20s: split screen, clues.\n20–25s: the winner.","visual":"T8 Reel cover. Split screen, 25s."},{"app":"dubid","hook":"My captain scores — my friend’s is on the bench","body":"0–5s: a goal on TV.\n5–10s: victory dance.\n10–15s: message to the friend: “😂”.","visual":"T8 Reel cover. Fast meme, 15s."},{"app":"all","hook":"What did your dad tell you at your first match?","body":"0–10s: three people answer on camera (street/office).\n10–20s: moving answers.\n20–25s: “What’s yours? Comments.”","visual":"T8 Reel cover. Street interviews, 25s, soft music."},{"app":"offsides","hook":"How long does it take to open an arena? 7 seconds.","body":"0–7s: screen recording with a timer.\n7–12s: sent to the group chat.\n12–15s: “Who’s in?”","visual":"T8 Reel cover. Timer on screen, 15s."},{"app":"fanlife","hook":"My LIFE: from kid to terrace","body":"0–5s: the pixel kid.\n5–15s: a montage of choices.\n15–22s: the moment at the ground.\n22–25s: “What’s your story?”","visual":"T8 Reel cover. Gameplay montage, nostalgic music, 25s."},{"app":"theworker","hook":"I got the whole lineup of a historic match","body":"0–3s: “11 slots. No cheating.”\n3–22s: one drag after another.\n22–28s: the score.","visual":"T8 Reel cover. 28s screen recording."},{"app":"all","hook":"Supporters describe their club in one word","body":"5–6 supporters of different clubs.\nEnd: “And here, everyone has one home.”","visual":"T8 Reel cover. Street interviews, 25s."},{"app":"dubid","hook":"The pick from the hated club — in slow motion","body":"0–8s: a trembling hand over a card.\n8–12s: tap.\n12–15s: “What have I done…”","visual":"T8 Reel cover. Over-the-top drama, 15s."},{"app":"fanlife","hook":"Legends Manager: draft legends in 30 seconds","body":"0–3s: badge reveal.\n3–25s: slot machine, picks.\n25–30s: the finished XI.","visual":"T8 Reel cover. Screen recording with slot sounds."},{"app":"offsides","hook":"What do you do when your team loses? Predict it right.","body":"0–5s: the team loses, sad face.\n5–10s: “At least I called it.”\n10–15s: shows the points.","visual":"T8 Reel cover. Bittersweet meme, 15s."},{"app":"all","hook":"Year after year: the same seat in the stand","body":"Montage (stock/illustration) of the same seat across decades.\nEnd: “Some things never change.”","visual":"T8 Reel cover. Nostalgic montage, 20s."},{"app":"theworker","hook":"The most beautiful Hapoel shirt ever — from the archive","body":"0–15s: fast scroll through shirts.\n15–20s: “Which is yours? Comments.”","visual":"T8 Reel cover. Archive scroll, 20s."},{"app":"dubid","hook":"My whole round in 15 seconds","body":"A fast ticker of points going up.\nEnd: “And you?”","visual":"T8 Reel cover. Motion graphics, 15s."},{"app":"fanlife","hook":"I was there: every ground I’ve visited","body":"0–10s: the Away Days map filling up.\n10–18s: “How many have you got?”","visual":"T8 Reel cover. Map screen recording, 18s."},{"app":"offsides","hook":"The craziest prediction that worked","body":"A short story: “I called an away win — and it happened.”\nEnd: “Share your craziest pick.”","visual":"T8 Reel cover. Storytelling to camera, 20s."},{"app":"all","hook":"What do people say at a 90th-minute goal? (censored)","body":"Funny beeps over supporters’ reactions.\nEnd: “We get you.”","visual":"T8 Reel cover. Comedy with beeps, 15s."},{"app":"fanlife","hook":"Every world, every club","body":"Fast cuts between 8 club pages, each in its colours.\nEnd: “Where’s your home?”","visual":"T8 Reel cover. Smooth transitions, 20s."},{"app":"all","hook":"A whole month with you — thank you","body":"A montage of the page’s best moments.\nEnd: “This is only the start.”","visual":"T8 Reel cover. Emotional montage, 30s."}],"STORIES":[{"app":"fanlife","hook":"Poll: home shirt or away shirt?","body":"Poll sticker: “Home ❤️ / Away 🖤”\nFrame 2: “Build yours in FAN LIFE” + link sticker","visual":"T5 Story frame. Two shirts side by side."},{"app":"dubid","hook":"Slider: how sure are you about your captain?","body":"Slider sticker 🔥\nFrame 2: link to your lineup","visual":"T5 Story frame. Red background, big type."},{"app":"theworker","hook":"Quiz: in which decade did Hapoel win the Asian Champion Club Tournament?","body":"Quiz sticker, 4 options (the right answer: the 1960s — it was 1967).\nFrame 2: “12 more gates waiting” + link","visual":"T5 Story frame. Vintage quiz card."},{"app":"offsides","hook":"Poll: who wins tonight?","body":"Poll sticker with the two teams of today’s big match.\nFrame 2: “Predict it for real — in the arena” + link","visual":"T5 Story frame. VS with two illustrated crests."},{"app":"all","hook":"Question: what was the first match you saw at a ground?","body":"Question sticker.\nFrames 2–3: we share the best answers.","visual":"T5 Story frame. An old ticket."},{"app":"fanlife","hook":"This or that: easy trivia or expert?","body":"Poll.\nFrame 2: “There’s both” + link","visual":"T5 Story frame. Two buttons of different sizes."},{"app":"dubid","hook":"Quiz: how many players do you pick in DUBID?","body":"Options: 11 / 14 / 15 / 18 (the answer: one from every club).\nFrame 2: link","visual":"T5 Story frame. A big question mark."},{"app":"offsides","hook":"Slider: how smart are you at football?","body":"Slider 🧠.\nFrame 2: “Prove it” + arena link","visual":"T5 Story frame. A drawn brain with a ball."},{"app":"theworker","hook":"Poll: the best centre-back in Hapoel history?","body":"Open question.\nFrame 2: “Vote on THE WORKER ballot” + link","visual":"T5 Story frame. A ballot slip."},{"app":"all","hook":"One emoji for your team this week","body":"Emoji slider 😭➡️😍","visual":"T5 Story frame. Split red-blue background."},{"app":"fanlife","hook":"Poll: LIFE — would you go to the ground alone at 8?","body":"Yes / No.\nFrame 2: “In LIFE you decide” + link","visual":"T5 Story frame. Pixel kid at a gate."},{"app":"dubid","hook":"Question: who’s your captain this week?","body":"Question sticker. We post the top picks tonight.","visual":"T5 Story frame. A captain’s armband."},{"app":"offsides","hook":"Quiz: how many points for an exact score?","body":"3 / 4 / 5 / 10 (5).\nFrame 2: link","visual":"T5 Story frame. Graffiti numbers."},{"app":"theworker","hook":"This or that: old Bloomfield or new?","body":"Poll.\nFrame 2: “Both are in THE WORKER”","visual":"T5 Story frame. Two drawings of the stadium."},{"app":"all","hook":"Countdown to the weekend","body":"Countdown sticker to the next matchday.\n“Set a reminder”","visual":"T5 Countdown card. An hourglass."},{"app":"fanlife","hook":"Poll: all-time XI — 4-3-3 or 4-4-2?","body":"Poll.\nFrame 2: “Build it in gate 1” + link","visual":"T5 Story frame. Two formation diagrams."},{"app":"dubid","hook":"Slider: how much does picking from the hated club hurt?","body":"Slider 😖.","visual":"T5 Story frame. A twisted face."},{"app":"offsides","hook":"Poll: a goal in the first half tonight?","body":"Yes / No.\nFrame 2: “Questions like this, live, on OFFSIDES”","visual":"T5 Story frame. A half-time clock."},{"app":"theworker","hook":"Quiz: which number is the curva gate at Bloomfield?","body":"3 / 5 / 7 / 11 (5).\nFrame 2: link","visual":"T5 Story frame. A gate with a hidden number."},{"app":"all","hook":"Admit it: have you ever shouted at a TV?","body":"Yes / Yes.\n(There’s no other option 😂)","visual":"T5 Story frame. An old TV with a drawn crack."},{"app":"fanlife","hook":"Question: which ground in Europe do you dream of?","body":"Question sticker.\nFrame 2: “Away Days — mark where you’ve been”","visual":"T5 Story frame. A map of Europe."},{"app":"dubid","hook":"Poll: goalkeeper or striker as captain?","body":"Poll.\nFrame 2: link","visual":"T5 Story frame. Gloves vs boots."},{"app":"offsides","hook":"Slider: how confident is today’s pick?","body":"Slider 🎯.\nFrame 2: arena link","visual":"T5 Story frame. A target and an arrow."},{"app":"theworker","hook":"Poll: shirt with a sponsor or without?","body":"Poll.\nFrame 2: “An archive of 168 shirts”","visual":"T5 Story frame. A clean shirt vs a sponsored one."},{"app":"all","hook":"Question: which terrace song do you love most?","body":"Question sticker (song titles only — no lyrics).","visual":"T5 Story frame. A drawn megaphone."},{"app":"fanlife","hook":"This or that: Legends Manager or Royal Rumble?","body":"Poll.\nFrame 2: “Both in gate 9”","visual":"T5 Story frame. Two badges."},{"app":"dubid","hook":"Quiz: what scores points in DUBID?","body":"Goal / Assist / Clean sheet / All of them (all of them).\nFrame 2: link","visual":"T5 Story frame. Three icons."},{"app":"offsides","hook":"Poll: friends or strangers?","body":"Arena with friends / Public arena.\nFrame 2: link","visual":"T5 Story frame. Two groups of figures."},{"app":"all","hook":"Slider: how much did you enjoy the page this month?","body":"Slider ❤️.\nFrame 2: “What do you want to see next?” (question)","visual":"T5 Story frame. A big red heart."},{"app":"all","hook":"Last question: what do we do next month?","body":"Open question sticker. You decide.","visual":"T5 Story frame. A styled question mark."}],"DEEP":[{"app":"theworker","hook":"Some nights have no match. For those, there’s the archive.","body":"Thousands of matches, hundreds of players, 168 shirts — every fact with a source.\nA good night for digging.","visual":"T1 Quote card. An open archive box with tickets and photos."},{"app":"fanlife","hook":"A night without football? No chance.","body":"13 gates of games are waiting in FAN LIFE. Pick a gate and walk in.","visual":"T3 Club collage. A wall of gates lit at night."},{"app":"all","hook":"The calm before the storm.","body":"The weekend is coming. Time to set the lineup, think about predictions, and remember why we love this.","visual":"T1 Quote card. An empty stand at dusk."},{"app":"fanlife","hook":"Tomorrow you’ll be smarter.","body":"One trivia round a night — and every week you know your club a little better.","visual":"T2 App feature card. A desk lamp over a question card."},{"app":"theworker","hook":"Tonight: gate 13, the timeline.","body":"Cards from history — put them in order. Sounds easy? Try it.","visual":"T2 App feature card. A red line with cards."},{"app":"dubid","hook":"Tonight is planning time.","body":"No deadline pressure: go through the clubs, pick your 14, save.","visual":"T2 App feature card. A notebook with 14 blurred names."},{"app":"fanlife","hook":"Legends Manager: a whole season in one evening.","body":"Draft, substitutions, highlights. Nobody will tell you to go to bed.","visual":"T2 App feature card. A moon over a pixel stadium."},{"app":"all","hook":"When did you fall in love with football?","body":"Write to us. The best stories go up next week (with your permission).","visual":"T1 Quote card. An envelope with a red heart."},{"app":"theworker","hook":"The memory game: pairs from history.","body":"Every pair of cards — a real moment from Hapoel’s past.","visual":"T2 App feature card. Cards with drawn players."},{"app":"fanlife","hook":"The shirt market is open even without a match.","body":"Got a spare shirt? Looking for a 90s shirt? It’s all there, no commission.","visual":"T4 Kit card. A table with a pile of folded shirts."},{"app":"all","hook":"Football is a language. We speak it.","body":"In Greek, Hebrew, German, Bosnian — the same love. FAN LIFE connects them all.","visual":"T3 Club collage. Scarves of different clubs tied together."},{"app":"fanlife","hook":"Daily Blind Cow","body":"A new player every day. The same clues for everyone. Who guessed fastest?","visual":"T2 App feature card. A blackboard with chalk clues."},{"app":"theworker","hook":"Hapoel Ussishkin — a story that needs no help.","body":"A whole memorial wing about the hall and its crowd. A good night to read.","visual":"T1 Quote card. An old hall door with a sign."},{"app":"dubid","hook":"Followed the injuries this week?","body":"Every squad change can change your round. A good night to check.","visual":"T6 Meme card. A tongue-in-cheek medical chart."},{"app":"fanlife","hook":"The shirt studio: design your own.","body":"Colour, pattern, collar, sponsor, crest, number. The shirt you always wanted.","visual":"T4 Kit card. A half-designed shirt with a colour palette."},{"app":"all","hook":"Tag the friend who always predicts wrong.","body":"He knows who he is. We don’t judge. The arena does.","visual":"T6 Meme card. A pointing finger."},{"app":"theworker","hook":"Every player — a shirt from his season.","body":"In THE WORKER’s all-time XI no player stands without a shirt. Build yours.","visual":"T4 Kit card. A pitch with red shirts."},{"app":"fanlife","hook":"I was there — mark your matches.","body":"Every match you attended gets a stamp. Your story builds itself.","visual":"T2 App feature card. An ink stamp “I was there”."},{"app":"all","hook":"Put the phone down for a minute. Or don’t.","body":"We’re here when you want to play, remember, or just argue.","visual":"T1 Quote card. A phone face-down on a sofa."},{"app":"fanlife","hook":"Your story in LIFE continues where you left it.","body":"The next chapter is waiting. What will you choose this time?","visual":"T2 App feature card. An open book with pixel art."},{"app":"dubid","hook":"A private league: invite the crew tonight.","body":"One link in the group — and tomorrow everyone competes.","visual":"T6 Meme card. A chat bubble with a link."},{"app":"theworker","hook":"The kit quiz: 5 shirts, 5 parts.","body":"Body, sleeves, sponsor, maker, crest. Who builds the perfect shirt?","visual":"T4 Kit card. Five parts scattered round a shirt."},{"app":"all","hook":"Football at night is something else.","body":"The lights, the cold, the scarf. What’s your best night-match memory?","visual":"T1 Quote card. Floodlights in the fog."},{"app":"fanlife","hook":"Legends Manager: your club’s legends, a whole season.","body":"Draft, captain, half-time changes — and pixel highlights. A good night to build a dynasty.","visual":"T2 App feature card. The Legends Manager badge over a tactics board."},{"app":"theworker","hook":"Hapoel polls — your slip.","body":"Eight questions, one printed slip, and you can share it.","visual":"T2 App feature card. A slip with a pen."},{"app":"fanlife","hook":"The memory game — night edition.","body":"Gate 6: cards, pairs, stories. Quiet, focus, then “Yes!”.","visual":"T2 App feature card. Cards on a wooden table at night."},{"app":"all","hook":"We’re building this for you.","body":"Every app here was built by a supporter, for supporters. Tell us what’s missing.","visual":"T1 Quote card. A desk with sketches."},{"app":"dubid","hook":"Who leads the monthly table?","body":"Try to get into the top ten before the month ends.","visual":"T2 App feature card. A table with ten rows highlighted."},{"app":"fanlife","hook":"Royal Rumble live: a room with friends.","body":"Everyone builds an XI from the same list — the better builder wins.","visual":"T2 App feature card. A table with four phones."},{"app":"all","hook":"Have a good week, family.","body":"New week, new matches, new memories. We’re here.","visual":"T1 Quote card. Sunset over a city, a stadium in the distance."}],"WALLPAPER":[{"app":"all","hook":"Wallpaper: “Football. Forever.”","body":"Save it as your lock screen. Tag us when you set it.","visual":"T5 Wallpaper 9:16. Huge type on cream paper, grain."},{"app":"theworker","hook":"Wallpaper: Gate 5","body":"A lock screen for Hapoel supporters. Save ✔","visual":"T5 Wallpaper 9:16. Gate 5 with rays, red and navy."},{"app":"fanlife","hook":"Wallpaper: 8 clubs, one universe","body":"Pick your club’s colour — the wallpaper is ready.","visual":"T5 Wallpaper 9:16, 8 colour versions (one per club)."},{"app":"all","hook":"Wallpaper: “You don’t choose a club”","body":"Save it. Send it to your dad.","visual":"T5 Wallpaper 9:16. White handwriting over a black-and-white stand."},{"app":"dubid","hook":"Wallpaper: “1 from every club”","body":"A lock screen for DUBID players.","visual":"T5 Wallpaper 9:16. A 14-dot grid."},{"app":"offsides","hook":"Wallpaper: “Told you so”","body":"The official wallpaper of people who are always right.","visual":"T5 Wallpaper 9:16. Orange neon at night."},{"app":"fanlife","hook":"Wallpaper: vintage shirt","body":"An archive shirt as your wallpaper. Which decade are you?","visual":"T5 Wallpaper 9:16. A shirt on a hanger, fabric background."},{"app":"all","hook":"Wallpaper: “Matchday”","body":"Set it every Saturday morning.","visual":"T5 Wallpaper 9:16. “MATCHDAY” with a ticket."},{"app":"theworker","hook":"Wallpaper: Ussishkin","body":"Never forget.","visual":"T5 Wallpaper 9:16. A dark hall with a beam of light."},{"app":"fanlife","hook":"Wallpaper: LIFE","body":"The kid who put on his first shirt.","visual":"T5 Wallpaper 9:16. Pixel art."},{"app":"all","hook":"Story background: “Where are you watching the match?”","body":"Download, add your location, tag us.","visual":"T5 Story frame 9:16. A drawn frame with room for a photo."},{"app":"offsides","hook":"Wallpaper: 🧨","body":"The currency of pride. Worth €0, worth everything.","visual":"T5 Wallpaper 9:16. A huge drawn 🧨."},{"app":"dubid","hook":"Wallpaper: “A little neighbourhood, a lot of football”","body":"A lock screen.","visual":"T5 Wallpaper 9:16. A drawn street bench."},{"app":"all","hook":"Wallpaper: the stand at night","body":"Save it for days without a match.","visual":"T5 Wallpaper 9:16. A floodlit stand, smoke."},{"app":"fanlife","hook":"Wallpaper: Legends Manager","body":"The new badge as your wallpaper.","visual":"T5 Wallpaper 9:16. The Legends badge on night."},{"app":"theworker","hook":"Wallpaper: the 1949 shirt","body":"The first in the archive.","visual":"T5 Wallpaper 9:16. An old red shirt."},{"app":"all","hook":"Story background: “My first match”","body":"Fill in the details and tag us.","visual":"T5 Story frame 9:16. A ticket template to fill in."},{"app":"offsides","hook":"Wallpaper: “Predict every moment”","body":"Your wallpaper for the month.","visual":"T5 Wallpaper 9:16. A clock and a pitch."},{"app":"fanlife","hook":"Wallpaper: the Away Days map","body":"Every ground in Europe as your wallpaper.","visual":"T5 Wallpaper 9:16. An ink map."},{"app":"all","hook":"Wallpaper: “Wedding or derby?”","body":"Send it to a friend who’s getting married.","visual":"T5 Wallpaper 9:16. Two buttons."},{"app":"dubid","hook":"Wallpaper: captain’s armband","body":"Your captain, always.","visual":"T5 Wallpaper 9:16. A red armband."},{"app":"theworker","hook":"Wallpaper: the timeline","body":"A hundred years in one picture.","visual":"T5 Wallpaper 9:16. A vertical red line."},{"app":"all","hook":"Story background: “My seat in the stand”","body":"Shoot your seat and tag us.","visual":"T5 Story frame 9:16. A drawn frame."},{"app":"fanlife","hook":"Wallpaper: the FAN LIFE seal","body":"The logo as a clean wallpaper.","visual":"T5 Wallpaper 9:16. The round seal on cream."},{"app":"offsides","hook":"Wallpaper: the podium","body":"Every day you try to get there.","visual":"T5 Wallpaper 9:16. A lit podium."},{"app":"all","hook":"Wallpaper: “Same club. Different journeys.”","body":"Save it.","visual":"T5 Wallpaper 9:16. A red thread joining dots."},{"app":"theworker","hook":"Wallpaper: the hammer","body":"The historic mark, clean.","visual":"T5 Wallpaper 9:16. Screenprint."},{"app":"fanlife","hook":"Wallpaper: the memory game","body":"Cards as your wallpaper.","visual":"T5 Wallpaper 9:16. A grid of cards."},{"app":"dubid","hook":"Wallpaper: “Locked”","body":"Set it after you lock your lineup.","visual":"T5 Wallpaper 9:16. A padlock on a pitch."},{"app":"all","hook":"Wallpaper: “Thank you”","body":"Thank you for a whole month.","visual":"T5 Wallpaper 9:16. Handwriting."}],"NIGHT":[{"app":"all","hook":"Good night to everyone still staring at the table.","body":"Tomorrow is another day. The club is still there. So are we.","visual":"T1 Quote card. Small white text on black, intimate."},{"app":"all","hook":"How was your day as a supporter? 1–10.","body":"No judging. Only the truth, in the comments.","visual":"T1 Quote card. Numbers 1–10 in one line."},{"app":"fanlife","hook":"Today’s story goes into tomorrow’s LIFE.","body":"Every supporter’s day is a chapter. FAN LIFE keeps them.","visual":"T1 Quote card. A book closing on a night table."},{"app":"theworker","hook":"A red night.","body":"There are good days and hard days. The red stays.","visual":"T1 Quote card. Full red with a single word."},{"app":"all","hook":"We never forget matches. We forget where we put the keys.","body":"A supporter’s memory is a strange thing. Share your sharpest one.","visual":"T1 Quote card. Keys on a table next to an old ticket."},{"app":"offsides","hook":"Today’s arenas are closing. The table is updating.","body":"Who climbed? We find out in the morning.","visual":"T1 Quote card. A midnight clock over a table."},{"app":"all","hook":"Good night, and don’t dream about the referee.","body":"😂 See you tomorrow.","visual":"T6 Meme card. A drawn referee with a pillow."},{"app":"dubid","hook":"Today’s points are already being counted.","body":"Check them tomorrow morning — with coffee, not before.","visual":"T1 Quote card. A coffee cup next to a face-down phone."},{"app":"all","hook":"The best thing your dad said to you at a match?","body":"One sentence. In the comments.","visual":"T1 Quote card. Two silhouettes, one tall, one small."},{"app":"fanlife","hook":"Every club. Every night. The same love.","body":"In Athens, Tel Aviv, Glasgow, Hamburg — tonight everyone dreams the same dream.","visual":"T3 Club collage. A map with small lights in cities."},{"app":"theworker","hook":"Good night to the reds.","body":"Whatever the score, the red stays.","visual":"T1 Quote card. A red star in the sky."},{"app":"all","hook":"Close your eyes. 90th minute. Goal.","body":"Now go to sleep smiling.","visual":"T1 Quote card. Tiny text in the middle of a black screen."},{"app":"all","hook":"How many matches did you watch today?","body":"We won’t judge. We watched four too.","visual":"T6 Meme card. Three TVs showing different matches."},{"app":"offsides","hook":"Your best prediction today?","body":"Tell us — tomorrow we pick the sharpest.","visual":"T1 Quote card. A twinkling star."},{"app":"fanlife","hook":"The archive never sleeps.","body":"Every night something new goes in. Another shirt, another match, another memory.","visual":"T1 Quote card. Shelves of archive boxes in the dark."},{"app":"all","hook":"To everyone whose team lost today: we’re here.","body":"Tomorrow we start again. Always.","visual":"T1 Quote card. A hand on a shoulder, warm light."},{"app":"all","hook":"To everyone whose team won today: enjoy it.","body":"But quietly. There are neighbours.","visual":"T6 Meme card. A supporter celebrating quietly under a blanket."},{"app":"dubid","hook":"Round tomorrow? Don’t forget to lock.","body":"A small reminder before bed.","visual":"T1 Quote card. A drawn bell."},{"app":"theworker","hook":"The night the whole city was red.","body":"History has nights like that. Which one do you remember?","visual":"T1 Quote card. The Tel Aviv skyline in red."},{"app":"all","hook":"Football connects people who would never talk otherwise.","body":"Tell us about the most unlikely friend you made on the terrace.","visual":"T1 Quote card. Two strangers hugging at a goal, silhouette."},{"app":"fanlife","hook":"What would you tell yourself at 8 about your club?","body":"A LIFE question. Answer in the comments.","visual":"T1 Quote card. A kid in a shirt too big for him."},{"app":"all","hook":"Good night. Matchday tomorrow?","body":"Check the fixtures — see you in the morning.","visual":"T1 Quote card. A calendar with a red circle."},{"app":"offsides","hook":"Your streak is waiting for tomorrow.","body":"Just come in once a day. That’s all.","visual":"T1 Quote card. A small flame in the dark."},{"app":"all","hook":"Three weeks together already.","body":"Thanks to everyone who comments, shares and plays. This page is yours.","visual":"T1 Quote card. A big 3, gentle confetti."},{"app":"theworker","hook":"Remember the people who built the club.","body":"Workers, supporters, volunteers. Good night to all of them.","visual":"T1 Quote card. A grainy archive-style crowd (illustration)."},{"app":"all","hook":"What’s the last thing you do before a match?","body":"A ritual? A song? Food? Share it.","visual":"T1 Quote card. An alarm clock at 7:00."},{"app":"fanlife","hook":"Good night from all 8 clubs.","body":"Olympiacos, Panathinaikos, AEK, Hapoel Tel Aviv, Hapoel Petah Tikva, Celtic, St. Pauli, Zrinjski.","visual":"T3 Club collage. Eight points of light in the sky."},{"app":"all","hook":"Whatever happened today — there’s football tomorrow.","body":"The one promise that’s always kept.","visual":"T1 Quote card. Sunrise over a pitch."},{"app":"dubid","hook":"The monthly table closes soon.","body":"You’ve got a few more rounds to climb.","visual":"T1 Quote card. A rising arrow."},{"app":"all","hook":"Thank you for a month. This is only the start.","body":"Save the page, turn on notifications — next month is bigger.","visual":"T1 Quote card. A hand-drawn red heart."}],"DERBY_NIGHT":[{"app":"fuckyou","hook":"Derby day. You know what you feel.","body":"There’s one place to let it out — anonymous, no account.\nPut a name up. Everyone who agrees backs it. Derby days only.\n(Players, referees and rivals — never private people.)","visual":"T6 Meme card. A black poster with torn white letters."},{"app":"fuckyou","hook":"After the derby you need to vent.","body":"FUCK YOU is open tonight. Anonymous. Funny. Freeing.\nNo private people’s names — only football.","visual":"T6 Meme card. A broken megaphone on red."},{"app":"fuckyou","hook":"The derby is over. The feeling isn’t.","body":"How many people agree with you? There’s a way to find out — completely anonymous.","visual":"T6 Meme card. A huge “agree” counter."}],"PRE":[{"club":{"app":"fanlife","hook":"Today: {home} vs {away}. Ready?","body":"{league}, {kickoff}.\nBefore kick-off — step into the club’s home on FAN LIFE: trivia, history and its favourite gate.","visual":"T5 Match poster. Two crests (illustrated), big kick-off time."},"il":{"app":"dubid","hook":"Today in the Israeli Premier League: {home} – {away}","body":"Kick-off {kickoff}. Are your DUBID players in? Check now.","visual":"T5 Match poster. Two team colours and the time."},"big":{"app":"offsides","hook":"Tonight: {home} – {away}","body":"{league}, {kickoff}. Open an arena with your friends before kick-off.","visual":"T5 Match poster. Night poster with floodlights."}},{"club":{"app":"fanlife","hook":"Matchday. {home} – {away}.","body":"The club’s home on FAN LIFE has a game for every one of its 13 gates. After the whistle — we talk.","visual":"T5 Match poster. A styled ticket with both names."},"il":{"app":"offsides","hook":"Your prediction for {home} – {away}?","body":"Half-time, full-time, first scorer. The arena is open now. {kickoff}.","visual":"T5 Match poster. Three prediction cards."},"big":{"app":"offsides","hook":"{home} – {away}: who takes it?","body":"Poll in the comments, the real call in the arena. {kickoff}.","visual":"T5 Match poster. Big VS in two colours."}},{"club":{"app":"fanlife","hook":"{kickoff}. {home} – {away}. Heart’s already racing.","body":"Time to put the shirt on. No shirt? There’s a studio on FAN LIFE.","visual":"T5 Match poster. A shirt on a hanger by the door."},"il":{"app":"dubid","hook":"Is your captain playing today?","body":"{home} – {away} at {kickoff}. Lock your lineup before it’s too late.","visual":"T5 Match poster. An open padlock, a clock."},"big":{"app":"offsides","hook":"Tonight we find out who knows: {home} – {away}","body":"Flash questions during the match — keep the app open.","visual":"T5 Match poster. A ⚡ notification over a pitch."}},{"club":{"app":"fanlife","hook":"A question before {home} – {away}","body":"Who is the club’s all-time top scorer? FAN LIFE’s trivia knows.","visual":"T5 Match poster. A question card with the crest."},"il":{"app":"offsides","hook":"Arena open: {home} – {away}","body":"Send it to the group, predict, tease. {kickoff}.","visual":"T5 Match poster. A styled arena screenshot."},"big":{"app":"offsides","hook":"Today’s classic: {home} – {away}","body":"Predict, tease, win. {kickoff}.","visual":"T5 Match poster. A dramatic poster."}},{"club":{"app":"fanlife","hook":"Everyone’s on the way to the ground. {home} – {away}.","body":"Staying home? You’re on the terrace too. At the ground? Mark “I was there” on FAN LIFE.","visual":"T5 Match poster. A scarf and a backpack on the way to the stadium."},"il":{"app":"dubid","hook":"The round is on: {home} – {away}","body":"Your DUBID points start moving at {kickoff}.","visual":"T5 Match poster. A points counter."},"big":{"app":"offsides","hook":"Momentum tonight: {home} – {away}","body":"A goal in the first 10 minutes? Answer live.","visual":"T5 Match poster. A momentum graph."}}],"LIVE":[{"club":{"app":"fanlife","hook":"Now: {home} – {away}","body":"We’re watching together. Tell us in the comments what’s happening where you are.\nAt half-time — quick trivia on FAN LIFE.","visual":"T5 Story frame. A live story with a red “LIVE”."},"il":{"app":"offsides","hook":"Flash questions are live: {home} – {away}","body":"The next question can land any second. Be there.","visual":"T5 Story frame. A ⚡ notification."},"big":{"app":"offsides","hook":"LIVE: {home} – {away}","body":"The arena is running. The questions are coming. Who’s leading?","visual":"T5 Story frame. A live story."}},{"club":{"app":"fanlife","hook":"Moments before kick-off: {home} – {away}","body":"Send one emoji for how you feel.","visual":"T5 Story frame. A story with an emoji slider."},"il":{"app":"dubid","hook":"Is your captain on the pitch?","body":"{home} – {away} now. Every goal = points.","visual":"T5 Story frame. A captain’s armband."},"big":{"app":"offsides","hook":"The ball is rolling: {home} – {away}","body":"Momentum is open. Answer fast.","visual":"T5 Story frame. A ball in motion."}},{"club":{"app":"fanlife","hook":"At half-time: one question from the archive","body":"{home} – {away} is on. At half-time — a quick question from the club’s FAN LIFE.","visual":"T5 Story frame. A question card."},"il":{"app":"offsides","hook":"Is your half-time prediction still alive?","body":"{home} – {away}. Check the arena.","visual":"T5 Story frame. An HT scoreboard."},"big":{"app":"offsides","hook":"Who leads the arena? {home} – {away}","body":"The table is live. Check where you are.","visual":"T5 Story frame. A live table."}}],"LAUNCH":{"reel":{"app":"all","hook":"We opened a page. Five apps, one supporter.","body":"0–3s: “If you’re a supporter — stop.”\n3–20s: fast cuts between FAN LIFE, THE WORKER, DUBID, OFFSIDES and FUCK YOU.\n20–25s: “Follow. A whole month starts tomorrow.”","visual":"T8 Reel cover. Fast montage of 5 screens, terrace sound, 25s."},"story":{"app":"all","hook":"Launch poll: what kind of supporter are you?","body":"4 options: Predictor / Manager / Historian / Nostalgic.\nFrame 2: “There’s an app for each” + link sticker.","visual":"T5 Story frame. Four comic icons."},"night":{"app":"all","hook":"The page’s first night. Thank you for being here.","body":"Tomorrow at 8 a.m. — the first post of a whole month.\nTurn on notifications.","visual":"T1 Quote card. White text on black."}}}'::jsonb)
